import { describe, expect, it } from 'vitest';
import { cOutline } from './cOutline';

describe('the overview of generated C code', () => {
  it("lists the compiler's section comments, with shorter titles for the longest", () => {
    const code = [
      '/* FILE GENERATED BY THE BLOQQI COMPILER */',
      '/* Typedefs */',
      '#include <stdbool.h>',
      '/* Structs representing variables (state, input, output) */',
      'typedef struct {',
      '  /* not at the start of a line */',
      '  Int state; /* nor alone on its line */',
      '} Acc_STATE;',
      '/* Structs representing return values */',
      '/* Function definitions */',
      'void Main(Main_STATE* _state) {',
      '}',
    ].join('\n');
    expect(cOutline(code)).toEqual([
      { title: 'Typedefs', comment: 'Typedefs', line: 2 },
      {
        title: 'Variable structs',
        comment: 'Structs representing variables (state, input, output)',
        line: 4,
      },
      { title: 'Return value structs', comment: 'Structs representing return values', line: 9 },
      { title: 'Function definitions', comment: 'Function definitions', line: 10 },
    ]);
  });

  it('is empty for code without section comments', () => {
    expect(cOutline('int main() {}\n')).toEqual([]);
  });
});
